sp_widget.client_script:
api.controller = function($scope, $window, $timeout) {
    var c = this;

    c.form = {
        application: '',
        opportunity: '',
        round: 'Technical Round',
        mode: 'Online',
        date: '',
        interviewer: '',
        meeting_link: ''
    };

    c.editingInterview = null;
    c.error = '';
    c.success = '';
    c.saving = false;

    c.applicationChanged = function() {
        if (!c.form.application || !c.data.applications) return;
        c.data.applications.forEach(function(app) {
            if (app.sys_id === c.form.application) {
                if (app.opportunity_sys_id) {
                    c.form.opportunity = app.opportunity_sys_id;
                }
            }
        });
    };

    c.schedule = function() {
        c.error = '';
        c.success = '';

        if (!c.form.application) {
            c.error = 'Please select a candidate.';
            return;
        }
        if (!c.form.opportunity) {
            c.error = 'Please select an opportunity.';
            return;
        }
        if (!c.form.round) {
            c.error = 'Please select an interview round.';
            return;
        }
        if (!c.form.mode) {
            c.error = 'Please select an interview mode.';
            return;
        }
        if (!c.form.date) {
            c.error = 'Please select the interview date & time.';
            return;
        }
        if (!c.form.interviewer || !c.form.interviewer.trim()) {
            c.error = 'Please enter the interviewer name.';
            return;
        }

        c.saving = true;

        c.server.get({
            action: 'schedule',
            form: {
                application: c.form.application,
                opportunity: c.form.opportunity,
                round: c.form.round,
                mode: c.form.mode,
                date: c.form.date,
                interviewer: c.form.interviewer.trim(),
                meeting_link: c.form.meeting_link || ''
            }
        }).then(function(res) {
            c.saving = false;
            if (res && res.data && res.data.success) {
                c.success = res.data.message || 'Interview scheduled successfully!';
                c.error = '';

                // Reset form
                c.form = {
                    application: '',
                    opportunity: '',
                    round: 'Technical Round',
                    mode: 'Online',
                    date: '',
                    interviewer: '',
                    meeting_link: ''
                };

                // Refresh recent scheduled list
                if (res.data.scheduledInterviews) {
                    c.data.scheduledInterviews = res.data.scheduledInterviews;
                } else {
                    c.refreshData();
                }
            } else {
                c.error = (res && res.data && res.data.error) ? res.data.error : 'Unable to schedule interview.';
            }
        }).catch(function(err) {
            c.saving = false;
            c.error = 'Communication error while scheduling interview.';
        });
    };

    c.openEdit = function(interview) {
        c.editingInterview = angular.copy(interview);
    };

    c.closeEdit = function() {
        c.editingInterview = null;
    };

    c.saveEdit = function() {
        if (!c.editingInterview) return;
        c.saving = true;
        c.server.get({
            action: 'update_interview',
            interview_sys_id: c.editingInterview.sys_id,
            interview_round: c.editingInterview.round,
            interview_mode: c.editingInterview.mode,
            interviewer: c.editingInterview.interviewer,
            meeting_link: c.editingInterview.meeting_link,
            status: c.editingInterview.status,
            result: c.editingInterview.result
        }).then(function(res) {
            c.saving = false;
            c.editingInterview = null;
            c.refreshData();
        }).catch(function() {
            c.saving = false;
        });
    };

    c.refreshData = function() {
        c.server.get().then(function(res) {
            if (res && res.data) {
                c.data = res.data;
            }
        });
    };

    c.goDashboard = function() {
        $window.location.href = '?id=campus360_recruiter_dashboard_new';
    };

    c.goBack = function() {
        $window.location.href = '?id=campus360_recruiter_interviews_new';
    };
};

sp_widget.css:
.schedule-page {
  padding: 24px 32px;
  background: #f8fafc;
  min-height: 100vh;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
}

.eyebrow {
  font-size: 10px;
  font-weight: 800;
  color: #7c3aed;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.page-header h1 {
  font-size: 26px;
  font-weight: 900;
  color: #0f172a;
  margin: 4px 0;
}

.page-header p {
  font-size: 13px;
  color: #64748b;
  margin: 0;
}

.header-actions {
  display: flex;
  gap: 10px;
}

.btn-secondary {
  background: #ffffff;
  color: #475569;
  border: 1px solid #cbd5e1;
  padding: 8px 14px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 12px;
  cursor: pointer;
}

.btn-secondary:hover {
  background: #f1f5f9;
  color: #1e293b;
}

.form-card, .scheduled-list-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 24px;
  margin-bottom: 28px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.02);
}

.form-title h2 {
  font-size: 18px;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 4px;
}

.form-title p {
  font-size: 12px;
  color: #64748b;
  margin: 0 0 20px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.form-group {
  display: flex;
  flex-direction: column;
}

.form-group.full-width {
  grid-column: 1 / -1;
}

.form-group label {
  font-size: 12px;
  font-weight: 700;
  color: #334155;
  margin-bottom: 6px;
}

.form-group label span {
  color: #ef4444;
}

.form-control, select {
  height: 40px;
  padding: 8px 12px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  font-size: 13px;
  color: #0f172a;
  background: #ffffff;
  outline: none;
}

.form-control:focus, select:focus {
  border-color: #7c3aed;
  box-shadow: 0 0 0 3px rgba(124, 58, 237, 0.1);
}

.field-help {
  font-size: 11px;
  color: #64748b;
  margin-top: 4px;
}

.form-footer {
  margin-top: 20px;
  display: flex;
  justify-content: flex-end;
}

.btn-primary {
  background: #7c3aed;
  color: #ffffff;
  border: none;
  padding: 10px 24px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(124, 58, 237, 0.3);
}

.btn-primary:hover {
  background: #6d28d9;
}

.scheduled-list-card .card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.scheduled-list-card h3 {
  font-size: 16px;
  font-weight: 800;
  color: #0f172a;
  margin: 0;
}

.scheduled-list-card p {
  font-size: 11px;
  color: #64748b;
  margin: 2px 0 0;
}

.scheduled-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.scheduled-table th {
  background: #f8fafc;
  color: #475569;
  font-weight: 800;
  padding: 10px 12px;
  border-bottom: 1px solid #e2e8f0;
  text-align: left;
}

.scheduled-table td {
  padding: 10px 12px;
  border-bottom: 1px solid #f1f5f9;
  color: #1e293b;
  vertical-align: middle;
}

.badge {
  padding: 3px 8px;
  border-radius: 12px;
  font-size: 10px;
  font-weight: 800;
}

.badge-round { background: #f3e8ff; color: #7c3aed; }
.badge-mode { background: #e0f2fe; color: #0284c7; }
.badge-status { background: #fef3c7; color: #d97706; }
.badge-result { background: #f1f5f9; color: #475569; }

.btn-edit {
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid #cbd5e1;
  background: #ffffff;
  color: #334155;
  font-size: 11px;
  cursor: pointer;
}

.btn-edit:hover {
  background: #f8fafc;
  color: #7c3aed;
  border-color: #7c3aed;
}

.edit-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999999;
}

.edit-modal {
  background: #ffffff;
  border-radius: 16px;
  width: 480px;
  max-width: 90vw;
  padding: 20px;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
}

.edit-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.edit-modal-header h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 800;
  color: #0f172a;
}

.btn-close {
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
  color: #64748b;
}

.edit-modal-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.edit-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 18px;
}

sp_widget.script:
(function() {

    var APPLICATION_TABLE = "x_snc_campus360_student_application";
    var STUDENT_ASSESSMENT_TABLE = "x_snc_campus360_student_assessment";
    var RECRUITER_ASSESSMENT_TABLE = "x_snc_campus360_recruiter_assessment";
    var INTERVIEW_TABLE = "x_snc_campus360_recruiter_interview";
    var OPPORTUNITY_TABLE = "x_snc_campus360_placement_opportunity";
    var COMPANY_TABLE = "x_snc_campus360_company_master";

    data.success = false;
    data.error = "";
    data.message = "";
    data.interview_id = "";

    data.company_name = "Campus360 Placement Cell";
    data.company_id = "CMP001";
    data.recruiter_name = "Recruiter Officer";

    // Handle AJAX actions
    if (input) {
        if (input.action === "schedule") {
            handleSchedule(input.form);
            return;
        }
        if (input.action === "update_interview") {
            handleUpdateInterview(input);
            return;
        }
    }

    // Synchronize Passed status & load candidates
    loadCandidatesAndOpportunities();
    loadRecentInterviews();

    function loadCandidatesAndOpportunities() {
        data.applications = [];
        data.opportunities = [];
        var eligibleMap = {};
        var oppMap = {};

        // 1. Sync Recruiter Assessments Passed -> Student Assessment & Application
        var raGR = new GlideRecord(RECRUITER_ASSESSMENT_TABLE);
        raGR.addEncodedQuery("result=Passed^ORresult=passed^ORresult=Pass");
        raGR.query();
        while (raGR.next()) {
            var appSysId = raGR.getValue("application");
            var stuSysId = raGR.getValue("student");
            var oppSysId = raGR.getValue("opportunity");

            if (appSysId) {
                var appGR = new GlideRecord(APPLICATION_TABLE);
                if (appGR.get(appSysId)) {
                    if (appGR.getValue("assessment_status") !== "Passed") {
                        appGR.setValue("assessment_status", "Passed");
                        appGR.update();
                    }
                }
            }

            if (stuSysId) {
                var saGR = new GlideRecord(STUDENT_ASSESSMENT_TABLE);
                saGR.addQuery("student", stuSysId);
                if (oppSysId) saGR.addQuery("opportunity", oppSysId);
                saGR.query();
                while (saGR.next()) {
                    if (saGR.getValue("result") !== "Passed") {
                        saGR.setValue("result", "Passed");
                        saGR.setValue("status", "Completed");
                        saGR.update();
                    }
                }
            }
        }

        // 2. Collect applications with Assessment Status = Passed or having Passed Assessment
        var appQueryGR = new GlideRecord(APPLICATION_TABLE);
        appQueryGR.addEncodedQuery("assessment_status=Passed^ORassessment_status=passed^ORassessment_status=Pass");
        appQueryGR.query();
        while (appQueryGR.next()) {
            addCandidate(appQueryGR);
        }

        // 3. Fallback: Collect applications matching Passed Student Assessments
        var saQueryGR = new GlideRecord(STUDENT_ASSESSMENT_TABLE);
        saQueryGR.addEncodedQuery("result=Passed^ORresult=passed^ORresult=Pass");
        saQueryGR.query();
        while (saQueryGR.next()) {
            var sStudent = saQueryGR.getValue("student");
            var sOpp = saQueryGR.getValue("opportunity");
            if (sStudent) {
                var appMatchGR = new GlideRecord(APPLICATION_TABLE);
                appMatchGR.addQuery("student", sStudent);
                if (sOpp) appMatchGR.addQuery("opportunity", sOpp);
                appMatchGR.query();
                while (appMatchGR.next()) {
                    if (appMatchGR.getValue("assessment_status") !== "Passed") {
                        appMatchGR.setValue("assessment_status", "Passed");
                        appMatchGR.update();
                    }
                    addCandidate(appMatchGR);
                }
            }
        }

        function addCandidate(appRecord) {
            var aSysId = appRecord.getUniqueValue();
            if (eligibleMap[aSysId]) return;

            // Check if active interview already scheduled
            var existingIntGR = new GlideRecord(INTERVIEW_TABLE);
            existingIntGR.addQuery("application", aSysId);
            existingIntGR.addQuery("status", "Scheduled");
            existingIntGR.setLimit(1);
            existingIntGR.query();
            if (existingIntGR.hasNext()) {
                return;
            }

            var stuId = appRecord.getValue("student");
            var oppId = appRecord.getValue("opportunity");

            var studentName = appRecord.getDisplayValue("student") || stuId || "Candidate";
            var appId = appRecord.getDisplayValue("application_id") || appRecord.getValue("application_id") || aSysId;

            var oppTitle = "Placement Drive";
            if (oppId) {
                var oGR = new GlideRecord(OPPORTUNITY_TABLE);
                if (oGR.get(oppId)) {
                    oppTitle = oGR.getValue("opportunity_title") || oGR.getValue("title") || oppTitle;
                }
            }

            eligibleMap[aSysId] = true;
            data.applications.push({
                sys_id: aSysId,
                application_id: appId,
                student_sys_id: stuId,
                student_name: studentName,
                opportunity_sys_id: oppId,
                opportunity_title: oppTitle,
                label: studentName + " (" + appId + ") - " + oppTitle
            });

            if (oppId && !oppMap[oppId]) {
                oppMap[oppId] = true;
                data.opportunities.push({
                    sys_id: oppId,
                    label: oppTitle
                });
            }
        }
    }

    function handleSchedule(form) {
        if (!form || !form.application || !form.opportunity || !form.round || !form.mode || !form.date || !form.interviewer) {
            data.error = "Please fill in all required fields.";
            return;
        }

        var appGR = new GlideRecord(APPLICATION_TABLE);
        if (!appGR.get(form.application)) {
            data.error = "Candidate application record not found.";
            return;
        }

        var studentSysId = appGR.getValue("student");
        var opportunitySysId = form.opportunity || appGR.getValue("opportunity");
        var companySysId = "";

        if (opportunitySysId) {
            var oppGR = new GlideRecord(OPPORTUNITY_TABLE);
            if (oppGR.get(opportunitySysId)) {
                companySysId = oppGR.getValue("company") || "";
            }
        }

        // Generate clean Interview ID
        var interviewId = "INT" + new Date().getTime();

        var interviewGR = new GlideRecord(INTERVIEW_TABLE);
        interviewGR.initialize();
        interviewGR.setValue("interview_id", interviewId);
        interviewGR.setValue("application", appGR.getUniqueValue());
        interviewGR.setValue("student", studentSysId);
        interviewGR.setValue("opportunity", opportunitySysId);
        if (companySysId) interviewGR.setValue("company", companySysId);
        interviewGR.setValue("interview_date", form.date);
        interviewGR.setValue("interview_mode", form.mode);
        interviewGR.setValue("interview_round", form.round);
        interviewGR.setValue("interviewer", form.interviewer);
        interviewGR.setValue("meeting_link", form.meeting_link || "");
        interviewGR.setValue("status", "Scheduled");
        interviewGR.setValue("result", "Pending");

        var newSysId = interviewGR.insert();

        if (newSysId) {
            // Update Student Application
            appGR.setValue("interview_status", "Scheduled");
            appGR.setValue("assessment_status", "Passed");
            appGR.update();

            // Update Student Assessment
            var saGR = new GlideRecord(STUDENT_ASSESSMENT_TABLE);
            saGR.addQuery("student", studentSysId);
            if (opportunitySysId) saGR.addQuery("opportunity", opportunitySysId);
            saGR.query();
            while (saGR.next()) {
                saGR.setValue("result", "Passed");
                saGR.setValue("status", "Completed");
                saGR.update();
            }

            // Update Recruiter Assessment
            var raGR = new GlideRecord(RECRUITER_ASSESSMENT_TABLE);
            raGR.addQuery("application", appGR.getUniqueValue());
            raGR.query();
            while (raGR.next()) {
                raGR.setValue("result", "Passed");
                raGR.setValue("status", "Completed");
                raGR.update();
            }

            data.success = true;
            data.interview_id = interviewId;
            data.message = "Interview " + interviewId + " successfully scheduled for candidate " + (appGR.getDisplayValue("student") || "Student") + ".";
        } else {
            data.error = "Could not create recruiter interview record.";
        }
    }

    function handleUpdateInterview(input) {
        if (!input.interview_sys_id) {
            data.error = "Interview ID required.";
            return;
        }

        var intGR = new GlideRecord(INTERVIEW_TABLE);
        if (intGR.get(input.interview_sys_id)) {
            if (input.interview_date) intGR.setValue("interview_date", input.interview_date);
            if (input.interview_mode) intGR.setValue("interview_mode", input.interview_mode);
            if (input.interview_round) intGR.setValue("interview_round", input.interview_round);
            if (input.interviewer) intGR.setValue("interviewer", input.interviewer);
            if (input.meeting_link !== undefined) intGR.setValue("meeting_link", input.meeting_link);
            if (input.status) intGR.setValue("status", input.status);
            if (input.result) intGR.setValue("result", input.result);
            intGR.update();

            data.success = true;
            data.message = "Interview record updated successfully.";
        }
    }

    function loadRecentInterviews() {
        data.scheduledInterviews = [];
        var intGR = new GlideRecord(INTERVIEW_TABLE);
        intGR.orderByDesc("sys_created_on");
        intGR.setLimit(15);
        intGR.query();
        while (intGR.next()) {
            data.scheduledInterviews.push({
                sys_id: intGR.getUniqueValue(),
                interview_id: intGR.getValue("interview_id") || intGR.getUniqueValue(),
                student_name: intGR.getDisplayValue("student") || "Student",
                opportunity_title: intGR.getDisplayValue("opportunity") || "Placement Drive",
                round: intGR.getValue("interview_round") || "Technical Round",
                mode: intGR.getValue("interview_mode") || "Online",
                date: intGR.getDisplayValue("interview_date") || intGR.getValue("interview_date") || "Scheduled",
                interviewer: intGR.getValue("interviewer") || "Recruiter",
                status: intGR.getValue("status") || "Scheduled",
                result: intGR.getValue("result") || "Pending",
                meeting_link: intGR.getValue("meeting_link") || ""
            });
        }
    }

})();
